import { test } from "node:test";
import assert from "node:assert/strict";
import { findRoute } from "../../src/routes/index.ts";

test("GET /version reports the app version", () => {
  const route = findRoute("GET", "/version");
  assert.ok(route, "GET /version is registered");
  assert.deepEqual(route.handler(), { version: "0.3.0" });
});
